arguments.new_string:
    self.show_default = show_default
    self.show_choices = show_choices

def on_validate_error(self, message: TextType) -> TextType:
    """
    Check if the console has markup disabled and suggest enabling it if the error
    message contains markup.
    """
    if not self.console.is_markup_enabled():
        if "[prompt.invalid]" in message or "[prompt.invalid.choice]" in message:
            return Text(
                f"{message}\n\n[yellow]Note: Markup is disabled in the console. Try running with --force-color or enabling markup to see styled errors.[/yellow]",
                style="prompt.error"
            )
    return message

    _prompt = cls(
        prompt,
        console=console,
        password=password,
        choices=choices,
        case_sensitive=case_sensitive,
        show_default=show_default,
        show_choices=show_choices,
    )
    return _prompt(default=default, stream=stream)

def process_response(self, value: Any) -> Any:
    """Process the user response and validate it."""
    try:
        return super().process_response(value)
    except InvalidResponse as e:
        modified_message = self.on_validate_error(e.message)
        raise InvalidResponse(modified_message)
